Input: {"question": "What is the profession of S. John Ross?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0228-7a669d2c0d6b:d00", "start": 0, "end": 40, "text": "knew what the \"S\" in his name stood for."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0228-7a669d2c0d6b:d00", "start": 41, "end": 87, "text": "He was sometimes referred to as Scissors John."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0228-7a669d2c0d6b:d00", "start": 88, "end": 233, "text": "Ross Eastgate, a military historian and journalist, said of Ross that \"He was not tall in stature, but he was giant in Australian entertainment.\""}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0228-7a669d2c0d6b:d00", "start": 234, "end": 236, "text": "S."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0228-7a669d2c0d6b:d00", "start": 237, "end": 309, "text": "John Ross was born Sebastian John Ross, in Detroit, USA, April 24, 1919."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0228-7a669d2c0d6b:d00", "start": 310, "end": 470, "text": "Inspired by an artist that he saw at Michigan State Fair, he trained with the silhouette artist Budd-Jack, travelling around to different fairs for three years."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0228-7a669d2c0d6b:d00", "start": 471, "end": 500, "text": "He later worked in Hollywood."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0228-7a669d2c0d6b:d00", "start": 501, "end": 580, "text": "During World War II, he served in the Philippines, before a period in Australia"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0228-7a669d2c0d6b:d01", "start": 0, "end": 209, "text": "it began , he ’ s here , covered in sawdust , finding humanity in gnarled wood , baking 12-foot plaster birthday cakes for everyone , casting his brooms in resin and bronze , building robots and writing code ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0228-7a669d2c0d6b:d01", "start": 210, "end": 217, "text": "John D."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0228-7a669d2c0d6b:d01", "start": 218, "end": 294, "text": "Ross American , born 1946 Indianapolis , IN Indiana State University , B.A ."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0228-7a669d2c0d6b:d01", "start": 295, "end": 359, "text": "English , 1972 Herron School of Art , Indiana University , B.A ."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0228-7a669d2c0d6b:d01", "start": 360, "end": 501, "text": "Sculpture , 1992 Select Exhibitions SaatchiArt.com Featured Artist May 25 , 2020 Indianapolis Museum of Art Hoosier Salon Indianapolis , IN ."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0228-7a669d2c0d6b:d01", "start": 502, "end": 537, "text": "Water Tower Museum Louisville , KY."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0228-7a669d2c0d6b:d01", "start": 538, "end": 557, "text": "South Bend Regional"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0228-7a669d2c0d6b:d02", "start": 0, "end": 142, "text": "Award for a short stint as editor of \"Pyramid\" magazine, and was named to the Order of the Pineapple along with author Adam Gorightly in 2013."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0228-7a669d2c0d6b:d02", "start": 143, "end": 286, "text": "\"Risus 1.5\" was named Best Free RPG at RPGnet in 2001 and he contributed to \"Pulp Hero\" which received a Silver ENnie for Best Writing in 2006."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0228-7a669d2c0d6b:d02", "start": 287, "end": 437, "text": "Ross has been a named guest at several conventions including Technicon in 1995, 1997, and 1998; A-Kon in 2004 and 2009; and Starland Gamefest in 2013."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0228-7a669d2c0d6b:d02", "start": 438, "end": 492, "text": "Ross was a special guest at GameFest held in May 2014."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0228-7a669d2c0d6b:d02", "start": 493, "end": 495, "text": "S."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0228-7a669d2c0d6b:d02", "start": 496, "end": 539, "text": "John Ross was born as Samuel John Ross Jr.,"}}, "original_cards": [{"doc_id": "ramdocs-0228-7a669d2c0d6b:d00", "card_id": "ramdocs-0228-7a669d2c0d6b:d00:c0", "entity": "S. John Ross", "scope": "profession", "claim": "S. John Ross was a silhouette artist.", "answer": "silhouette artist", "quote": "Inspired by an artist that he saw at Michigan State Fair, he trained with the silhouette artist Budd-Jack, travelling around to different fairs for three years.", "original_document_number": 1}], "current_answers": ["silhouette artist", "journalist"], "candidate_answers": [{"candidate_id": "R0", "answer": "silhouette artist", "origin": "initial"}, {"candidate_id": "R1", "answer": "journalist", "origin": "coverage_addition"}]}
